[Form]
public class TFMCreateTranslationForm extends FormRun
{
    SysTableLookup      sysTableLookup;
    LanguageTable       LanguageTable;
    FormStringControl   mandatoryLanguageControl;

}

/// <summary>
///
/// </summary>
public void init()
{
    super();        

    FormGroupControl_NewTranslation.columns(1);

    // Add a translation per used language
    int i;
    SysTranslationHelper helper = new SysTranslationHelper(tableNum(TFMTranslations), tableNum(TFMTranslationLines));
    container conLanguage = SysTranslationDetailHelper::populateLanguageDropDown(helper.getTranslationTableId(), helper.getLanguageFieldId());
    container languages = conPeek(conLanguage, 3);

    LanguageId orgLanguage = SystemParameters::getSystemLanguageId();

    select firstonly LanguageTable where LanguageTable.LanguageId == orgLanguage;

    if(LanguageTable && LanguageTable.LanguageId)
    {
        str orgLanguageLabel = LanguageTable::languageId2Description(orgLanguage);
        mandatoryLanguageControl = this.addLocale(orgLanguage, orgLanguageLabel);
        mandatoryLanguageControl.mandatory(true);
    }

    for (i=5; i <= conlen(languages); i++)
    {
        if(orgLanguage != conpeek(languages, i))
        {
            this.addLocale(conpeek(languages, i), conpeek(languages, i+1));
        }
        i++;
    }

}

protected FormStringControl addLocale(str _locale, str _label)
{
    FormStringControl formStringControl = this.FormGroupControl_NewTranslation.addControl(FormControlType::String, _locale);
    formStringControl.label("@TFM:Translation" + _label);
    formStringControl.widthMode(FormWidth::SizeToAvailable);
    formStringControl.limitText(-1);
    return formStringControl;
}

/// <summary>
///
/// </summary>
public void clicked()
{
    FormStringControl       languageControl;
    FormBuildGroupControl   designFormControl;
    TFMTranslations         header;

    super();

    if(FormGroupControl_NewTranslation.enableChilds())
    {
        if(!element.LabelId_create_new.text())
        {
            info("@TFM:PleaseaddtheIDforthetranslation");
            return;
        }

        if(!element.mandatoryLanguageControl.text())
        {
            info("@TFM:Pleaseaddthetranslationforthesys");
            return;
        }

        // Create the languages in the TFMTranslationsLines.
        header = TFMTranslations::create(element.LabelId_create_new.text(), null);

        // Add or update the languages. Use the ID from the control (the locale) and the value as the translation on the line.
        designFormControl = element.form().design().control(element.FormGroupControl_NewTranslation.id());
        int noOfControls = designFormControl.controlCount();
        int i;
        for (i = 2; i <= noOfControls; i++)
        {
            languageControl = element.FormGroupControl_NewTranslation.controlNum(i) as FormStringControl;

            if(languageControl)
            {

                if(header)
                {
                    TFMTranslationLines::createTranslation(header.RecId, languageControl.text(), languageControl.name());
                }
            }
        }
    } 
    else
    {
        // Add the label file value
        str labelId = element.FormStringControl_LabelId.text();

        // remove the e.g. TFM: from labelId.
        int indexOfColon = strFind(labelId, ':', 0, strLen(labelId));

        str cleanedLabelId = (indexOfColon) ? subStr(labelId, indexOfColon+1, strLen(labelId) - indexOfColon) : labelId;
        TFMTranslations::create(cleanedLabelId, labelId); // we are not using the @ from the label.
    }

    element.close();
}
